class NomTipoNomina extends BaseNomTipoNomina {

    /**
     * Obtener un listado de los datos de los tipos de nómina.
     *
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los tipos de nómina.
     */
    public static function obtenerListadoTiposNomina($inicio = 0, $limite = 1000, $criterio) {
        $where = (!empty($criterio)) ? "denominacion ilike '%".$criterio."%'" : 'denominacion is not null';
        //Devolviendo el listado de tipos de nómina en forma de arreglo.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->from('NomTipoNomina')
            ->where($where)
            ->orderBy('denominacion ASC')
            ->limit($limite)
            ->offset($inicio)
            ->fetchArray():
            $query->from('NomTipoNomina')
            ->where($where)
            ->orderBy('denominacion ASC')
            ->fetchArray();
        return $result;
    }

    public static function obtenerListadoTiposNominaTotal() {
        //Devolviendo el listado de tipos de nómina en forma de arreglo.
        return Doctrine_Query::create()
            ->from('NomTipoNomina')
            ->orderBy('denominacion ASC')
            ->fetchArray();
    }
    /**
