    public static function obtenerCantidadTotalTiposNomina() {

        //Devolviendo la cantidad total de tipos de nómina.
        return Doctrine_Query::create()->select('COUNT(idtiponomina) AS cantidad')
            ->from('NomTipoNomina')
            ->fetchOne()
            ->cantidad;
    }

    /**
     * Obtener el tipo de nómina dado el identificador.
     *
     * @param int $idtiponomina    Identificador del tipo de nómina.
     * @return NomTipoNomina      Objeto tipo de nómina (clase del dominio).
     */
    public static function obtenerObjTipoNominaDadoId($idtiponomina) {
        return Doctrine::getTable('NomTipoNomina')->find($idtiponomina);
    }

    /**
     * Obtener si existe un tipo de nómina a partir de la denominación.
     *
     * @param int $idtnomin    		Identificador del tipo de nómina.
     * @param string $denom    	 	Denominación del tipo de nómina.
     *
     * @return boolean    			Si existe un tipo de nómina.
     */
    public static function existeTipoNomina($idtnomin, $denom) {

        $query = Doctrine_Query::create()->select('COUNT(idtiponomina) AS cantidad')
            ->from('NomTipoNomina')
            ->where("denominacion ilike ?", $denom);
        if($idtnomin){
            $query->addWhere('idtiponomina <> ?', $idtnomin);
        }

        return    $query->fetchOne()->cantidad;
    }

