    public static function existeDenominacionTipoNomina($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomTipoNomina p')
            ->where("p.denominacion=?", array($denominacion))
            ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
            ->execute();
        if(count($result)){
            return 1;
        }else{
            return 0;
        }
    }

