    public function findByIdOrDenom($denom, $idtiponomina = null)
    {
        try {
            $query = Doctrine_Query::create();
            $query->from('NomTipoNomina')
                ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
                ->andWhere("denominacion ilike '$denom'");
            if (!empty($idtiponomina)) {
                $query->andWhere("idtiponomina <> ?", $idtiponomina);
            }
            $result = $query->count();
            if ($result > 0) {
                return true;
            } else {
                return false;
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }

    public static function obtenerNominaCargoAsociadoporIdElaborarPago($idelaborarpago)
    {
        //Devolviendo la si hay cargoasociado para el tipo de nomina
        return Doctrine_Query::create()
            ->select('nomtn.cargoasociado')
            ->from('NomTipoNomina nomtn')
            ->innerJoin('nomtn.ConfigModeloNomina cmn')
            ->innerJoin('cmn.DatElaborarPagos dep')
            ->where('dep.idelaborarpagos = ?', array($idelaborarpago))
            ->fetchOne()
            ->cargoasociado;
    }

